P=[[2,2,2,2],[2,0,0,0],[2,0,2,0],[2,0,2,2]]
Q=[[2,2,2,2],[2,0,0,0],[2,0,0,2],[2,0,2,2]]
tiles={(0,j):P for j in range(4)}
tiles[(1,0)]=Q
tiles[(2,0)]=P; tiles[(2,3)]=P
tiles[(3,2)]=P; tiles[(3,3)]=P
grid=[[0]*19 for _ in range(19)]
for (i,j),tile in tiles.items():
    for a in range(4):
        for b in range(4):
            grid[i*5+a][j*5+b]=tile[a][b]
    if tile[i][j]==2:
        grid[i*5+i][j*5+j]=8
print('\n'.join(' '.join(map(str,row)) for row in grid))
